#!/usr/bin/env python3
"""R2 third-code cross-check: ABINIT 10.8.3 input matching a BAANDI `baandi dielectric` TOML (same cell/atoms/UPF/ecut/FFT grid/k mesh/bands).
Datasets: 1 = SCF (Gamma-centred kgrid, kptopt 1); 2 = NSCF on the Gamma-centred response mesh with nsym 1 and kptopt 1 (time reversal only; the screening driver requires timrev 2, kptopt 3 fails), nband = N_b + extra;
3 = screening (optdriver 3) at omega = 0 only (nfreqre 1, nfreqim 0), nband = N_b, ecuteps = E_cut^chi (Ha; npweps checked in the log),
inclvkb 2 (nonlocal commutator in the q -> 0 dipoles), RPA (no xc kernel). gw_qlwl is NOT set: ABINIT then uses its default small q
(1, 2, 3) * 1e-5 in reduced coordinates, so project the BAANDI/Yambo tensors onto q_hat = q_red.B / |q_red.B| when comparing.
Written by the dev08 session on 2026-11-27 (MIT, no ABINIT source).
Reads the TOML only (Python 3.11 tomllib), never UPF contents. usage: make_abinit_r2.py in.toml --ngfft N1 N2 N3 [--extra-bands 8] > case.abi"""
import argparse, tomllib
from pathlib import Path
ap = argparse.ArgumentParser(); ap.add_argument("toml"); ap.add_argument("--ngfft", nargs=3, type=int, required=True); ap.add_argument("--extra-bands", type=int, default=8)
a = ap.parse_args(); t = tomllib.loads(Path(a.toml).read_text())
sy, bs, rs = t["system"], t["basis"], t["response"]; assert sy.get("lattice_unit") == "bohr"
pp = t["pseudopotentials"]; species = sorted(pp); typ = {s: i + 1 for i, s in enumerate(species)}
Z = {"H":1,"Li":3,"C":6,"N":7,"F":9,"Al":13,"Si":14}
km = rs.get("k_mesh", bs["kgrid"]); kg = bs["kgrid"]; nb = rs["bands"]
L = [f"# Generated by make_abinit_r2.py from {Path(a.toml).name} (R2 third-code cross-check)", "ndtset 3", "acell 1.0 1.0 1.0",
     "rprim " + "\n      ".join(" ".join(repr(float(x)) for x in v) for v in sy["lattice_vectors"]),
     f"ntypat {len(species)}", "znucl " + " ".join(str(Z[s]) for s in species),
     f"natom {len(sy['atoms'])}", "typat " + " ".join(str(typ[x['species']]) for x in sy["atoms"]),
     "xred " + "\n     ".join(" ".join(repr(float(c)) for c in x["fractional"]) for x in sy["atoms"]),
     'pp_dirpath "."', 'pseudos "' + ", ".join(pp[s] for s in species) + '"',
     "ixc " + {"lda-pz": "2", "pbe": "11"}[t["xc"]["functional"]] + f"   # ABINIT native ({t['xc']['functional']}); ABINIT 10.8.3 cannot map the UPF1 string SLA PZ NOGX NOGC", f"ecut {float(bs['ecutwfc_ry']) / 2.0!r}", f"ngfft {a.ngfft[0]} {a.ngfft[1]} {a.ngfft[2]}", "occopt 1", "istwfk *1",
     "shiftk 0 0 0", "nshiftk 1",
     f"ngkpt1 {kg[0]} {kg[1]} {kg[2]}", "kptopt1 1", "tolvrs1 1.0d-14", "nstep1 200",
     f"ngkpt2 {km[0]} {km[1]} {km[2]}", "kptopt2 1", "nsym2 1", "iscf2 -2", "getden2 1", f"nband2 {nb + a.extra_bands}", f"nbdbuf2 {a.extra_bands}", "tolwfr2 1.0d-20", "nstep2 300",
     f"ngkpt3 {km[0]} {km[1]} {km[2]}", "kptopt3 1", "nsym3 1", "optdriver3 3", "getwfk3 2", f"nband3 {nb}", f"ecuteps3 {float(rs['ecut_chi_ha'])!r}",
     "inclvkb3 2", "nfreqre3 1", "nfreqim3 0", "gwcalctyp3 0", "awtr3 0", "symchi3 0"]
print("\n".join(L))
